class Solution {
  public int[] minimumWeight(int[][] edges, int[][] queries) {
    int n = edges.length + 1;
    int[] start = new int[n + 1];
    for (int[] e : edges) {
      start[e[0] + 1]++;
      start[e[1] + 1]++;
    }
    for (int i = 0; i < n; i++) start[i + 1] += start[i];
    int[] fill = new int[n], to = new int[2 * (n - 1)], w = new int[2 * (n - 1)];
    for (int[] e : edges) {
      int p = start[e[0]] + fill[e[0]]++;
      to[p] = e[1];
      w[p] = e[2];
      p = start[e[1]] + fill[e[1]]++;
      to[p] = e[0];
      w[p] = e[2];
    }
    int LOG = 1;
    while ((1 << LOG) < n) LOG++;
    int[][] up = new int[LOG + 1][n];
    int[] depth = new int[n];
    long[] dist = new long[n];
    int[] queue = new int[n];
    int head = 0, tail = 0;
    queue[tail++] = 0;
    up[0][0] = 0;
    boolean[] seen = new boolean[n];
    seen[0] = true;
    while (head < tail) {
      int u = queue[head++];
      for (int p = start[u]; p < start[u + 1]; p++) {
        int v = to[p];
        if (seen[v]) continue;
        seen[v] = true;
        up[0][v] = u;
        depth[v] = depth[u] + 1;
        dist[v] = dist[u] + w[p];
        queue[tail++] = v;
      }
    }
    for (int l = 1; l <= LOG; l++) for (int i = 0; i < n; i++) up[l][i] = up[l - 1][up[l - 1][i]];
    int[] ans = new int[queries.length];
    for (int qi = 0; qi < queries.length; qi++) {
      int a = queries[qi][0], b = queries[qi][1], c = queries[qi][2];
      long total =
          dist(a, b, up, depth, dist, LOG)
              + dist(a, c, up, depth, dist, LOG)
              + dist(b, c, up, depth, dist, LOG);
      ans[qi] = (int) (total / 2);
    }
    return ans;
  }

  private static long dist(int a, int b, int[][] up, int[] depth, long[] dist, int LOG) {
    int u = a, v = b;
    if (depth[u] < depth[v]) {
      int t = u;
      u = v;
      v = t;
    }
    int diff = depth[u] - depth[v];
    for (int l = 0; l <= LOG; l++) if ((diff >> l & 1) != 0) u = up[l][u];
    if (u != v) {
      for (int l = LOG; l >= 0; l--) {
        if (up[l][u] != up[l][v]) {
          u = up[l][u];
          v = up[l][v];
        }
      }
      u = up[0][u];
    }
    return dist[a] + dist[b] - 2 * dist[u];
  }
}
